/* eslint-disable @typescript-eslint/no-require-imports */
// Puts Andvari's icons and logos in the build in place of Bitwarden's (FR-BRAND-02, #3).
// Wired into apps/browser/webpack.base.js by ANDVARI-PATCH #3; upstream images and modules
// stay untouched in the tree. The assets are generated by scripts/andvari/brand/generate.js.
const path = require("path");

const CopyWebpackPlugin = require("copy-webpack-plugin");

const ASSETS = path.resolve(__dirname, "assets");

// Upstream module requests and the Andvari module that replaces each. `from` limits a
// replacement to requests made from that folder, for names too generic to match alone.
const REPLACEMENTS = [
  {
    request: /[\\/]bitwarden-(logo(-beta)?\.icon|icon)$/,
    from: path.join("libs", "assets", "src", "svg"),
    to: path.join(ASSETS, "andvari-logo.icon.js"),
  },
  {
    request: /[\\/]utils[\\/]svg-icons$/,
    from: path.join("apps", "browser", "src", "autofill"),
    to: path.join(ASSETS, "autofill-svg-icons.js"),
  },
  {
    request: /^\.[\\/]shield$/,
    from: path.join("apps", "browser", "src", "autofill", "content", "components", "icons"),
    to: path.join(ASSETS, "autofill-shield.js"),
  },
];

/**
 * @param {typeof import("webpack")} webpack
 * @returns {import("webpack").WebpackPluginInstance[]} plugins to add after upstream's CopyWebpackPlugin
 */
function brandPlugins(webpack) {
  return [
    // Same file names as upstream's: these overwrite the copies of src/images and src/popup/images.
    new CopyWebpackPlugin({
      patterns: [
        { from: path.resolve(__dirname, "images"), to: "images", force: true },
        { from: path.resolve(__dirname, "popup-images"), to: "popup/images", force: true },
      ],
    }),
    ...REPLACEMENTS.map(
      ({ request, from, to }) =>
        new webpack.NormalModuleReplacementPlugin(request, (resource) => {
          if (resource.context.includes(from)) {
            resource.request = to;
          }
        }),
    ),
  ];
}

module.exports = { brandPlugins, REPLACEMENTS };
